/* Soltech / Connected clarity. A single finishing layer for the comparison. */
@layer soltech-identity {
 :root {
  --canvas:#fff;--paper:#fff;--panel:#f5f6f8;--panel-hover:#eef1f6;
  --ink:#171c26;--paper-ink:#171c26;--muted:#606978;--paper-muted:#606978;
  --line:#e1e5eb;--paper-line:#e1e5eb;--control-line:#7e8999;
  --accent:#424c5d;--accent-hover:#252d3b;--accent-ink:#354054;--accent-soft:#eef0f4;
  --glass-edge:#d9dfe8;--glass-header:#f6f7f9;--glass-content:#fff;
  --glass-selected:#e9ecf0;--glass-well:#f3f5f8;--glass-button:#fff;--glass-blur:none;
  --card-border:#d5dbe4;--button-border:#c6ceda;--button-hover:#f3f5f9;
  --button-shadow:0 1px 2px #17243a08;--shadow:0 8px 28px #17243a08;
  --radius:20px;--small-radius:12px;--dock-space:108px;
  --tint-glass:linear-gradient(155deg,#ffffffed,#e4e8eecc 58%,#f6f7f9e8);--tint-control:#fff;--tint-track:#f7f8fa;--tint-blur:none;
