 .button.primary:not(.danger):not(.clear-address),.coin-check-form .button[type=submit]:not(.clear-address),.builder-actions .button[type=submit]:not(.danger){background:linear-gradient(155deg,#535e70,#303b4e);color:#fff;border-color:#303b4e;box-shadow:inset 0 1px 0 #ffffff3d,0 2px 4px #2631441a}
 .button.primary:not(.danger):hover:not(:disabled),.coin-check-form .button[type=submit]:hover:not(:disabled),.builder-actions .button[type=submit]:hover:not(:disabled){background:var(--accent-hover);border-color:var(--accent-hover);color:#fff}
