 .check-metrics{gap:0;border-block:1px solid var(--line);background:none}
 .check-metrics>div,.check-metrics>div:nth-child(n){padding:18px 0;border:0;border-radius:0;background:none;min-width:0}
 .check-metrics>div:nth-child(even){padding-left:22px;border-left:1px solid var(--line)}
