 .holdings-overview{border:0;border-block:1px solid var(--line);border-radius:0;padding:18px 0;background:transparent}
 .holdings-overview dl{gap:0}.holdings-overview dl>div{padding-right:16px}.holdings-overview dl>div+div{padding-left:20px;border-left:1px solid var(--line)}
 .holdings-overview dt{font-size:.8125rem}.holdings-overview dd{font-size:1.35rem}
 .check-more summary{padding-block:17px;min-height:54px}.check-more p,.section-note{font-size:.8125rem}
 .dex-boost-count.has-boosts{color:#7d5918;background:#fff9eb;border-color:#e8dbb8}
 .source-empty{border:1px solid var(--line);background:#f7f8fa;border-radius:12px;padding:17px}
 .report-panel.chart-panel{padding:0;border:0;background:#fff;border-radius:0}
 .history-mode{border:1px solid var(--button-border);border-radius:10px;background:#fff;box-shadow:none;font-size:.8125rem}
 .history-readout{margin:24px 0 18px;gap:6px}.history-readout strong{font-size:2.7rem;font-weight:600;letter-spacing:-.045em}
 .history-plot{height:310px}.history-axis{color:var(--muted)}
 .history-line{stroke:var(--accent);stroke-width:2}.history-point,.history-isolated{fill:var(--accent)}
 .history-cursor{stroke:#7787a7}.history-level{stroke:#a9b4c7}.history-baseline{stroke:#e8ecf1}
 .history-current{background:#f5f7fa;border-color:var(--line);border-radius:12px;padding:14px 16px}
 .history-ranges{margin-top:6px}.history-ranges button{min-height:42px}.history-estimate{color:var(--muted)}
 .check-pending{align-items:center;font-size:.875rem}.check-pending>span{font-size:0;width:26px;height:18px;position:relative;flex:none}
