 .check-pending>span::after{left:13px;background:#bdc7db;animation:paired-loading 1.1s ease-in-out infinite alternate}
 @keyframes paired-loading{from{opacity:.35;transform:translateY(2px)}to{opacity:1;transform:translateY(-2px)}}
 /* Check coin preview: white planes held by a fine, light-catching silver rim. */
 .checker .check-metrics{gap:10px;border:0;border-radius:0;background:transparent;box-shadow:none;overflow:visible}
 .checker .check-metrics>div:nth-child(n){padding:16px 14px;border:1px solid var(--line);border-radius:12px;background:transparent}
 @media(forced-colors:none){
  :root{--silver-panel-face:linear-gradient(150deg,#f5f7fa 0%,#eef1f5 60%,#e4e9f0 100%)}
