  .checker .coin-check-form{border-color:transparent;background:var(--silver-panel-face) padding-box,var(--silver-rim) border-box;box-shadow:inset 0 0 0 1px #fff,0 0 0 1px #e6e9ee,0 4px 12px #26314406}
  .app-header .main-nav{background:var(--silver-panel-face);border-color:#c5ccd5}
  .checker .check-address-input:not(:has(input[aria-invalid=true])){border-color:#7e8999;background:#fff;box-shadow:inset 0 1px 2px #303b4e08,0 1px 0 #fff}
  .checker .check-input-row .clear-address{background:linear-gradient(160deg,#fff,#f1f3f6);border-left-color:#d3d8e0;color:#424a56}
  .checker .check-input-row .clear-address:hover:not(:disabled){background:#e9edf2;color:#171c26}
  .checker .check-input-row .clear-address:disabled{background:#f8f9fb;color:#727b89}
  .checker .coin-check-form .button[type=submit]:not(.clear-address){background:linear-gradient(155deg,#303335,#181b1d);border-color:#202426;color:#fff;box-shadow:inset 0 1px 0 #ffffff24,0 1px 3px #17212b16}
  .checker .coin-check-form .button[type=submit]:hover:not(:disabled){background:linear-gradient(155deg,#3a3e40,#232729);border-color:#202426;color:#fff}
  .checker .check-network select:not([aria-invalid=true]),.checker .history-mode{background-color:#fff;border-color:#7e8999;box-shadow:inset 0 1px 0 #fff,0 1px 0 #e6e9ee}
  .checker .report-tabs,.checker .history-ranges{background:var(--silver-panel-face);border-color:#c5ccd5;box-shadow:inset 0 1px 0 #fff,0 1px 0 #e9ecf0}
  .checker .report-tabs::before,.checker .history-ranges::before{background:var(--silver-face);border-color:#a6b0bd;box-shadow:inset 0 1px 0 #fff,inset 0 -1px 0 #c0c8d366,0 1px 3px #2631440c}
  .checker .report-tabs button[aria-selected=true],.checker .history-ranges button[aria-pressed=true]{color:#242b35}
