  .checker .project-link{background:var(--silver-face);border-color:#b9c2cf;color:#303946;box-shadow:inset 0 1px 0 #fff,inset 0 -1px 0 #d6dce566}
  .checker .project-link:hover{background:#edf0f4;border-color:#7e8999;color:#171c26}
  /* Selected A3 detail, borrowed only for the earlier address field. */
