  .checker .check-address-input:has(input[aria-invalid=true]){border:1px solid transparent;border-image:url('assets/address-cut-corner-error.svg') 18 fill / 18px / 0 stretch;background:transparent;box-shadow:none}
  .checker .check-input-row .check-address-input .clear-address{clip-path:polygon(0 0,calc(100% - 15px) 0,100% 15px,100% 100%,0 100%);border-radius:0 0 9px 0}
