 /* Scanner: one identity with connected, expandable source rows. */
 .personal-scanner,.personal-page{margin-inline:auto;max-width:720px}
 .single-scanner-card{padding:26px 0 22px;border:0;border-block:1px solid var(--line);border-radius:0;background:#fff;box-shadow:none;position:relative}
 .single-scanner-card::before{content:'';position:absolute;top:-1px;left:0;height:2px;width:44px;background:linear-gradient(90deg,var(--ink) 0 48%,transparent 48% 53%,#aeb8c8 53%)}
