 .finds-empty h2{font-size:1.6rem;margin-top:20px}.finds-empty p{margin:12px 0 24px;max-width:40ch;font-size:.9375rem}
 .feed-sources{margin:19px 0;font-size:.8125rem}.finds-explanation{padding:0;margin-top:28px;border-top:1px solid var(--line)}
 .finds-explanation summary{padding-block:17px;min-height:54px;font-size:.875rem}.finds-explanation li{font-size:.875rem}
 .scanner-mark.scanner-identity{box-shadow:inset 0 1px 0 #ffffff75,0 2px 3px #18243a10}
