 .personal-edit{font-size:.8125rem;padding:9px 14px;border-radius:10px}
 .personal-section{margin-top:28px}.personal-section>h2{font-size:.75rem;letter-spacing:.045em;text-transform:uppercase;color:var(--muted);margin:0 0 8px}
