 .source-tabs{border-radius:12px;background:#f5f6f8;box-shadow:none}.source-tabs button{border-radius:8px}
 .source-tabs button[aria-pressed=true]{background:#fff;border-color:#d4dce9;box-shadow:0 1px 2px #17243a08;color:var(--accent-ink)}
 .type-option,.choice-pill{border-radius:10px}.type-option:has(input:checked),.choice-pill:has(input:checked){background:#f1f3f6;border-color:var(--accent)}
 .match-option{border-radius:12px}.match-option:has(input:checked){background:#f4f6f9;border-color:#9ca8b9}
 .settings-group,.setup-guidance,.builder-example{border-color:var(--line);border-radius:12px;background:#f7f8fa;box-shadow:none}
 .setup-guidance{padding:17px 18px;border-left:3px solid #bbc4d1}.guidance-label{color:var(--muted);letter-spacing:.045em;font-size:.6875rem}
 .builder-example>p{color:var(--muted)}.builder-example li>span{border-radius:7px;border-color:#c1cbdb;color:#495b79}
 .builder-plan>div{padding:11px 0;font-size:.875rem}.builder-plan dt{max-width:50%}.builder-plan dd{font-weight:550}
 .appearance-options{border-radius:12px;background:#fff}.appearance-options label{border-radius:9px}
 .builder-actions{margin-top:28px;padding-top:22px;background:#fff}.builder-connection-note{font-size:.75rem}
 .scanner-board,.scanner-choice,.scanner-list-item,.mini-summary{background:#fff;box-shadow:none;border-color:var(--line);border-radius:14px;backdrop-filter:none;-webkit-backdrop-filter:none}
 .scanner-choice.selected{background:#fff;border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}
 .scanner-board .board-head{background:#f5f7fa;border-bottom-color:var(--line);box-shadow:none}
 dialog,.photo-crop-dialog{border-radius:20px;border-color:#d4dbe6;box-shadow:0 22px 64px #18243a26}
 dialog::backdrop{background:#17203055;backdrop-filter:blur(3px)}
 .field-help,.personal-local-copy{color:var(--muted)}
 .toast{background:#202734;color:#fff;box-shadow:0 8px 24px #151b2b26;border-radius:12px;font-weight:500;backdrop-filter:none}
 .loading{padding:48px 0}
 .loading h1{font-size:1.75rem}
 :focus-visible{outline:3px solid var(--accent);outline-offset:4px}
 .check-address-input input:focus-visible{outline:0}
 .check-address-input .clear-address:focus-visible{outline-offset:-4px}
 h1[tabindex='-1']:focus{outline:none}
 @media(max-width:800px){
  .app-shell{padding-inline:22px}.app-header{padding:13px 0;border:0;background:#ffffffed}
  .app-header::before{inset:0 -22px;background:#ffffffed;border-bottom:1px solid var(--line);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
  .brand{font-size:1.35rem}.brand-mark{width:30px;height:30px}.app-settings{width:42px;height:42px}
  .main-nav{left:18px;right:18px;bottom:max(12px,env(safe-area-inset-bottom));padding:5px;border-radius:21px;background:#ffffffed;box-shadow:0 6px 24px #18243a12,inset 0 1px 0 #fff;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
  .main-nav a{min-height:58px;font-size:.8125rem;gap:4px;padding:8px 3px;border-radius:16px;color:var(--muted)}
  .main-nav a svg{width:22px;height:22px}.nav-glass{left:5px;top:5px;bottom:5px;width:calc((100% - 10px)/4);border-radius:16px;background:var(--tint-glass);border-color:#c4ccd7;box-shadow:inset 0 1px 0 #fff,inset 0 -1px 0 #b6bfca38,0 2px 4px #27334a0a}
  .nav-glass::after{bottom:3px;width:10px;left:calc(50% - 5px)}
  .page-intro,.checker{margin-top:30px}.page-intro{margin-bottom:24px}
  .page-intro h1,.personal-page .page-intro h1,.checker-intro h1{font-size:2rem;line-height:1.16;letter-spacing:-.035em}
  .checker-intro{margin-bottom:24px}.checker-intro>p{font-size:.9375rem;max-width:28ch}
  .coin-check-form{padding:18px 16px;border-radius:17px}.coin-check-form::before{left:17px}
  .check-input-row{gap:12px}.check-input-row>button{min-height:50px}
  .checker-welcome{padding-top:25px}.checker-welcome>div{padding-inline:12px}.checker-welcome strong{font-size:.875rem}.checker-welcome p{font-size:.8125rem}
  .live-data-columns{grid-template-columns:1fr;gap:28px}.live-coin-head h2{font-size:1.6rem}.live-coin{padding-top:20px}
  .check-metrics dd{font-size:1.5rem}.check-metrics>div:nth-child(even){padding-left:18px}
  .history-readout strong{font-size:2.2rem}.history-plot{height:250px}.report-tabs{margin-block:20px}
  .single-scanner-heading{gap:10px}.single-scanner-identity{gap:12px}.single-scanner-identity .scanner-mark{width:46px;height:46px}
  .single-scanner-identity h2{font-size:1.125rem}.single-scanner-identity div>span{font-size:.75rem}.single-scanner-card .scanner-customize{padding-inline:11px}
  .personal-identity{gap:13px}.personal-identity .personal-avatar{width:58px;height:58px}.personal-identity-copy h2{font-size:1.125rem}
  .personal-row{padding-block:17px}.personal-identity-copy>span{font-size:.75rem}.personal-edit{padding-inline:12px}
  .guided-builder{padding-top:18px}.builder-heading h1{font-size:1.8rem}.builder-surface{padding-top:22px}
  .purpose-option{padding:18px 14px}.purpose-option .scanner-mark{width:44px;height:44px}
  .builder-actions{padding-bottom:12px}.builder-plan>div{gap:15px}
 }
 @media(max-width:360px){.app-shell{padding-inline:16px}.app-header::before{inset-inline:-16px}.main-nav{left:12px;right:12px}.checker-welcome>div{padding-inline:10px}.checker-welcome strong{font-size:.8125rem}.checker-welcome p{font-size:.75rem}}
 /* Supporting text should read clearly on silver, without competing with values. */
 .checker :is(.checker-intro>p,.check-privacy summary,.check-privacy p,.section-note,.check-more>p,.coin-subline,.report-meta,.history-coverage,.history-readout>span,.history-readout time,.history-current>small){color:#4b5563;font-weight:500}
 .checker :is(.check-label label span,.check-metrics dt,.check-detail-list dt,.holdings-overview dt,.check-activity thead th,.check-address>span){color:#3f4956;font-weight:550}
 .checker .check-privacy summary{font-size:.875rem}
 .checker :is(.summary-value small,.account-kind){font-size:.75rem;line-height:1.5;font-weight:500;color:#4b5563}
 .checker .check-activity thead th{font-size:.8125rem}
 .checker .check-address-input input::placeholder{color:#606b79;opacity:1}
 @media(max-width:360px){.checker .check-metrics dd:not(.metric-missing){font-size:1.25rem}}
 /* A clear glass-style thumb for the existing native chart slider. */
 .checker .history-scrubber{--scrub-track:#c4ccd7;--scrub-face:#fff;--scrub-edge:#7e8b9d;--scrub-shadow:none;--scrub-filter:none}
 .checker .history-scrubber::-webkit-slider-runnable-track{height:6px;border:0;border-radius:999px;background:var(--scrub-track)}
 .checker .history-scrubber::-moz-range-track{height:6px;border:0;border-radius:999px;background:var(--scrub-track)}
 .checker .history-scrubber::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;box-sizing:border-box;width:34px;height:26px;margin-top:-10px;border:1px solid var(--scrub-edge);border-radius:999px;background:var(--scrub-face);box-shadow:var(--scrub-shadow);backdrop-filter:var(--scrub-filter);-webkit-backdrop-filter:var(--scrub-filter)}
 .checker .history-scrubber::-moz-range-thumb{box-sizing:border-box;width:34px;height:26px;border:1px solid var(--scrub-edge);border-radius:999px;background:var(--scrub-face);box-shadow:var(--scrub-shadow);backdrop-filter:var(--scrub-filter)}
 .checker .history-scrubber:disabled{cursor:default;opacity:.55}
 @media(forced-colors:none){
  .checker .history-scrubber{--scrub-track:linear-gradient(180deg,#b9c3d1,#dce2ea);--scrub-face:linear-gradient(155deg,#fffffff0 0%,#ffffff80 38%,#ffffff24 62%,#ffffffc7 100%);--scrub-edge:#8492a4;--scrub-shadow:inset 0 1px 1px #fff,inset 0 -1px 1px #ffffffd9,0 2px 5px #25344929;--scrub-filter:blur(3px) saturate(1.08)}
  .checker .history-scrubber:active{--scrub-face:linear-gradient(155deg,#ffffffc7 0%,#ffffff4d 40%,#ffffff1a 64%,#ffffffa3 100%)}
  @media(prefers-reduced-transparency:reduce){.checker .history-scrubber,.checker .history-scrubber:active{--scrub-face:#fff;--scrub-filter:none;--scrub-shadow:0 1px 3px #25344929}}
 }
 @media(forced-colors:active){.checker .history-scrubber{--scrub-track:ButtonText;--scrub-face:ButtonFace;--scrub-edge:ButtonText;--scrub-shadow:none;--scrub-filter:none}}
 /* Clear moving lenses sit above the stationary silver surfaces. */
 @media(forced-colors:none){
  .app-shell .nav-glass,.checker .report-tabs::before,.checker .history-ranges::before{background:linear-gradient(145deg,#ffffffa8 0%,#ffffff24 44%,#ffffff08 70%,#ffffff70 100%);border-color:#ffffffd6;box-shadow:inset 0 1px 0 #fff,inset 0 -1px 1px #7080952b,0 2px 6px #2631441a;backdrop-filter:blur(8px) saturate(1.08);-webkit-backdrop-filter:blur(8px) saturate(1.08)}
  @media(prefers-reduced-transparency:reduce){.app-shell .nav-glass,.checker .report-tabs::before,.checker .history-ranges::before{background:#fff;border-color:#aeb9c8;backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:0 1px 3px #26314414}}
 }
 @media(prefers-reduced-motion:reduce){.app-shell .nav-glass,.checker .report-tabs::before,.checker .history-ranges::before{transition:none}}
 @media(prefers-reduced-transparency:reduce){.app-header,.app-header::before,.main-nav{background:#fff;backdrop-filter:none;-webkit-backdrop-filter:none}}
 @media(forced-colors:active){
  .checker .check-metrics>div:nth-child(n){border-color:ButtonText;background:Canvas;box-shadow:none}
  .coin-check-form,.check-address-input,.single-scanner-card,.personal-row,.purpose-option,.source-tabs,.report-tabs,.history-ranges{background:Canvas;border-color:ButtonText;box-shadow:none}
  .nav-glass,.report-tabs::before,.history-ranges::before,.source-tabs button[aria-pressed=true]{background:Canvas;border-color:Highlight;outline:1px solid Highlight}
  .button:not(.danger):not(.clear-address),.button.primary:not(.danger):not(.clear-address),.coin-check-form .button[type=submit]:not(.clear-address),.builder-actions .button[type=submit]:not(.danger){background:ButtonFace;color:ButtonText;border:1px solid ButtonText;box-shadow:none}
  .purpose-option:has(input:checked),.choice-pill:has(input:checked),.match-option:has(input:checked){outline:2px solid Highlight;background:Canvas}
  .check-address-input:has(input[aria-invalid=true]){border:2px solid Mark;box-shadow:none}
  .history-line,.history-cursor{stroke:CanvasText}.history-point{fill:Highlight}
 }
 @media(forced-colors:active){.nav-glass{border:1px solid Highlight;background:Canvas}.main-nav a[aria-current=page]{color:Highlight}.button.primary,.coin-check-form button[type=submit]{background:ButtonFace;color:ButtonText;border:1px solid ButtonText}.brand-period{color:CanvasText}.coin-check-form::before{background:CanvasText}}

 /* Scanner landing page: one quiet status card, with optional customization. */
 .scanner-status-card{padding:24px;border:1px solid #bcc5d0;border-radius:18px;background:#fff;box-shadow:0 2px 6px #24324506}
 .scanner-status-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px}
 .scanner-status-heading h2{min-width:0;font-size:1.25rem;font-weight:650;line-height:1.3;letter-spacing:-.025em;overflow-wrap:anywhere}
 .scanner-state{display:inline-flex;align-items:center;gap:7px;flex:none;padding:5px 10px;border:1px solid #d9dfe6;border-radius:999px;background:#f3f5f7;color:#505c6b;font-size:.8125rem;font-weight:600;line-height:1.5}
 .scanner-state-dot{width:6px;height:6px;border-radius:50%;background:#7a8593;flex:none}
 .scanner-status-copy{margin:14px 0 0;color:#556170;font-size:.875rem;line-height:1.6}
 .scanner-status-actions{display:flex;justify-content:flex-end;margin-top:24px}
 .scanner-status-actions .scanner-status-customize{min-height:44px;padding:10px 18px;font-size:.875rem;border-radius:11px}
 @media(max-width:600px){.scanner-status-card{padding:20px}.scanner-status-heading{gap:12px}}
 @media(forced-colors:active){.scanner-status-card{border-color:CanvasText;background:Canvas;box-shadow:none}.scanner-state{border-color:CanvasText;background:Canvas;color:CanvasText}.scanner-state-dot{background:CanvasText}.scanner-status-copy{color:CanvasText}}
}
